import{z as l,x as d,o as E,c as B,q as r,j as s,D as i,d as e,s as o,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"精简配置","description":"","frontmatter":{"title":"精简配置","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/thin-provisioning.md","filePath":"cs/thin-provisioning.md","lastUpdated":1791413859000}'),p={name:"cs/thin-provisioning.md"};function h(m,a,c,u,D,f){const n=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="精简配置" tabindex="-1">精简配置 <a class="header-anchor" href="#精简配置" aria-label="Permalink to &quot;精简配置&quot;">​</a></h1><div class="epigraph"><p>精简池只在第一次写入时分配后端块；逻辑卷可以声称比池更大，直到真正写满才 ENOSPC。</p><footer>—— 据 Linux dm-thin 文档；存储行业对 thin provisioning 的实践整理</footer></div><p><a href="/cs/dm-crypt">上一课</a>不改变「逻辑块总对应物理块」。<a href="/cs/sparse-files">稀疏文件</a> 是 FS 层的洞。设备层也可以：<strong>thin</strong>。缺口是 dm-thin 的池、元数据、以及丢弃如何还块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>虚拟机每人一块 100G 盘，实际平均用 10G。厚配置浪费。thin：逻辑设备 + 池；映射树（类似 extent）记录已写块。未映射读：返回零（或未定义，视实现）。写：分配池块，更新元数据（常有独立 metadata 设备）。缺口：池满时哪些卷失败；快照在 thin 上便宜（共享映射）；与 <a href="/cs/fs-quota">配额</a> 不同——这是块设备会计，不是 uid。</p><p><span class="marginnote">元数据耗尽与数据耗尽是两种满。thin 快照不是 btrfs subvol，但共享物理块的直觉相近。</span></p><p><span class="marginnote">数字实例：10 台虚拟机各挂 100G 盘，厚配置要备足 1T 物理空间；实际平均只写 10G，thin 池备 100G 就够——但&quot;还剩多少&quot;从购买时固定，变成了必须运行时监控才知道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一次写逻辑块 L：锁元数据，分配 P，写数据到 P，提交映射。读：查映射，无则零页。<code>discard</code> 删除映射，还池——<a href="/cs/discard-trim">TRIM</a> 后课。对照 LVM thick：创建时就切走 PV 空间。对照 FS fallocate：可在 thin 上仍触发分配，视是否传递。</p>',9)),(E(),s(A,null,{default:i(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20WR%5B%22%E5%86%99%E9%80%BB%E8%BE%91%E5%9D%97%22%5D%20--%3E%20MAP%5B%22thin%20%E6%98%A0%E5%B0%84%E6%A0%91%22%5D%0A%20%20MAP%20--%3E%7C%22%E6%9C%AA%E6%98%A0%E5%B0%84%22%7C%20ALLOC%5B%22%E6%B1%A0%E4%B8%AD%E5%88%86%E9%85%8D%22%5D%0A%20%20ALLOC%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%E5%9D%97%22%5D%0A%20%20RD%5B%22%E8%AF%BB%E6%9C%AA%E6%98%A0%E5%B0%84%22%5D%20--%3E%20ZERO%5B%22%E9%9B%B6%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"精简把超分配从管理承诺变成块层机制，使密度上升，也把「盘满」从创建时挪到运行时——监控变成必修。不要把它写成云计费产品课。与 RAID：thin 可叠在 md 上，池满与成员故障是不同失败。",-1)),a[5]||(a[5]=t("p",null,"崩溃：元数据必须日志或 COW，否则映射丢失——dm-thin 有自己的元数据事务。",-1)),a[6]||(a[6]=t("p",null,'池"满"有两种，后果与补救完全不同，监控要能区分：',-1)),(E(),s(A,null,{default:i(()=>[o(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E7%9B%91%E6%8E%A7%E6%B1%A0%E5%8D%A0%E7%94%A8%22%5D%20--%3E%20Q%7B%22%E5%93%AA%E4%B8%80%E7%A7%8D%E6%BB%A1%E4%BA%86%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%95%B0%E6%8D%AE%E6%B1%A0%E6%BB%A1%22%7C%20D%5B%22%E6%96%B0%E5%86%99%E5%85%A5%E5%A4%B1%E8%B4%A5%2C%20%E6%97%A7%E6%95%B0%E6%8D%AE%E6%97%A0%E6%8D%9F%22%5D%0A%20%20D%20--%3E%20FIX%5B%22%E5%9C%A8%E7%BA%BF%E6%89%A9%E7%89%A9%E7%90%86%E7%9B%98%E5%8D%B3%E5%8F%AF%E8%A1%A5%E6%95%91%22%5D%0A%20%20FIX%20--%3E%20OK%5B%22%E6%81%A2%E5%A4%8D%E5%86%99%E5%85%A5%22%5D%0A%20%20Q%20--%3E%7C%22%E5%85%83%E6%95%B0%E6%8D%AE%E8%AE%BE%E5%A4%87%E6%BB%A1%22%7C%20M%5B%22%E6%98%A0%E5%B0%84%E6%97%A0%E6%B3%95%E5%86%8D%E6%9B%B4%E6%96%B0%22%5D%0A%20%20M%20--%3E%20RO%5B%22%E6%95%B4%E6%B1%A0%E8%BD%AC%E5%8F%AA%E8%AF%BB%E6%88%96%E5%81%9C%E6%91%86%22%5D%0A%20%20RO%20--%3E%20HARD%5B%22%E8%A1%A5%E6%95%91%E8%A6%81%E7%A6%BB%E7%BA%BF%E6%89%A9%20metadata%20%E8%AE%BE%E5%A4%87%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：discard 像酒店退房——把&quot;这个房间我不住了&quot;告知前台，房间划回可用池；不退房（不发 discard），即使你早就不用了，物理块也一直被你占着。</span></p><p>实现上：元数据设备写满比数据池满更致命：映射无法更新，整池只读或失败。快照共享映射项，删除要延迟到引用为零，监控必须看 metadata 占用。 读法上只引用<a href="/cs/dm-crypt">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>精简配置</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CAS（内容寻址）重删的全部指纹。不保证每个 hypervisor 的 UNMAP 行为。下一课用快速盘给慢盘做缓存：bcache。</p><p>版本字段会变，课序钉的是机制对象「精简配置」，不是某一主线内核的结构体名。 后课默认：逻辑盘可超分配，写时占池。块层缓存数据盘，下一课 bcache。</p><p><span class="marginnote">常见误区：容易把精简配置与配额混为一谈。thin 管&quot;物理块何时才真正分配&quot;，是块层的会计；配额管&quot;某个 uid 最多能用多少&quot;，是文件系统对人的政策——两层各管各的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>thin 按首次写分配；读洞得零。</li><li>池与元数据会分别耗尽。</li><li>bcache 是下一课。</li><li>出处：Linux dm-thin；LVM thin 文档；<em>OSTEP</em> 对分配的背景。</li></ul>',10))])}const _=l(p,[["render",h]]);export{P as __pageData,_ as default};
